BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH t AS MATERIALIZED (SELECT ts_code,end_date,comp_type,ann_date,f_ann_date,revenue,total_revenue,oper_cost,operate_profit,n_income,n_income_attr_p,rd_exp,assets_impair_loss,credit_impa_loss,ebit,income_tax FROM core_serving.equity_income WHERE end_date IN (DATE '2018-12-31',DATE '2019-03-31',DATE '2019-06-30',DATE '2019-09-30',DATE '2019-12-31',DATE '2020-03-31',DATE '2020-06-30',DATE '2020-09-30',DATE '2020-12-31',DATE '2021-03-31',DATE '2021-06-30',DATE '2021-09-30',DATE '2021-12-31',DATE '2022-03-31',DATE '2022-06-30',DATE '2022-09-30',DATE '2022-12-31',DATE '2023-03-31',DATE '2023-06-30',DATE '2023-09-30',DATE '2023-12-31',DATE '2024-03-31',DATE '2024-06-30',DATE '2024-09-30',DATE '2024-12-31',DATE '2025-03-31',DATE '2025-06-30',DATE '2025-09-30',DATE '2025-12-31',DATE '2026-03-31',DATE '2026-06-30',DATE '2026-09-30')),
q AS (SELECT end_date,count(*) records,count(DISTINCT ts_code) codes,count(*) FILTER(WHERE comp_type='1') general_comp_codes,count(revenue) AS revenue_nonnull, count(total_revenue) AS total_revenue_nonnull, count(oper_cost) AS oper_cost_nonnull, count(operate_profit) AS operate_profit_nonnull, count(n_income) AS n_income_nonnull, count(n_income_attr_p) AS n_income_attr_p_nonnull, count(rd_exp) AS rd_exp_nonnull, count(assets_impair_loss) AS assets_impair_loss_nonnull, count(credit_impa_loss) AS credit_impa_loss_nonnull, count(ebit) AS ebit_nonnull, count(income_tax) AS income_tax_nonnull,count(*) FILTER(WHERE ann_date IS NULL OR f_ann_date IS NULL) missing_announcement FROM t GROUP BY end_date)
SELECT jsonb_build_object('section','income_period_coverage','as_of',current_timestamp,'data',coalesce(jsonb_agg(to_jsonb(q) ORDER BY end_date),'[]'::jsonb)) FROM q;
COMMIT;

BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH t AS MATERIALIZED (SELECT ts_code,end_date,comp_type,ann_date,f_ann_date,accounts_receiv,inventories,acct_payable,total_assets,total_liab,total_hldr_eqy_exc_min_int,total_hldr_eqy_inc_min_int,contract_assets,contract_liab,cip,goodwill,money_cap,st_borr,lt_borr FROM core_serving.equity_balancesheet WHERE end_date IN (DATE '2018-12-31',DATE '2019-03-31',DATE '2019-06-30',DATE '2019-09-30',DATE '2019-12-31',DATE '2020-03-31',DATE '2020-06-30',DATE '2020-09-30',DATE '2020-12-31',DATE '2021-03-31',DATE '2021-06-30',DATE '2021-09-30',DATE '2021-12-31',DATE '2022-03-31',DATE '2022-06-30',DATE '2022-09-30',DATE '2022-12-31',DATE '2023-03-31',DATE '2023-06-30',DATE '2023-09-30',DATE '2023-12-31',DATE '2024-03-31',DATE '2024-06-30',DATE '2024-09-30',DATE '2024-12-31',DATE '2025-03-31',DATE '2025-06-30',DATE '2025-09-30',DATE '2025-12-31',DATE '2026-03-31',DATE '2026-06-30',DATE '2026-09-30')),
q AS (SELECT end_date,count(*) records,count(DISTINCT ts_code) codes,count(*) FILTER(WHERE comp_type='1') general_comp_codes,count(accounts_receiv) AS accounts_receiv_nonnull, count(inventories) AS inventories_nonnull, count(acct_payable) AS acct_payable_nonnull, count(total_assets) AS total_assets_nonnull, count(total_liab) AS total_liab_nonnull, count(total_hldr_eqy_exc_min_int) AS total_hldr_eqy_exc_min_int_nonnull, count(total_hldr_eqy_inc_min_int) AS total_hldr_eqy_inc_min_int_nonnull, count(contract_assets) AS contract_assets_nonnull, count(contract_liab) AS contract_liab_nonnull, count(cip) AS cip_nonnull, count(goodwill) AS goodwill_nonnull, count(money_cap) AS money_cap_nonnull, count(st_borr) AS st_borr_nonnull, count(lt_borr) AS lt_borr_nonnull,count(*) FILTER(WHERE ann_date IS NULL OR f_ann_date IS NULL) missing_announcement FROM t GROUP BY end_date)
SELECT jsonb_build_object('section','balancesheet_period_coverage','as_of',current_timestamp,'data',coalesce(jsonb_agg(to_jsonb(q) ORDER BY end_date),'[]'::jsonb)) FROM q;
COMMIT;

BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH t AS MATERIALIZED (SELECT ts_code,end_date,comp_type,ann_date,f_ann_date,n_cashflow_act,c_fr_sale_sg,c_pay_acq_const_fiolta,depr_fa_coga_dpba,amort_intang_assets FROM core_serving.equity_cashflow WHERE end_date IN (DATE '2018-12-31',DATE '2019-03-31',DATE '2019-06-30',DATE '2019-09-30',DATE '2019-12-31',DATE '2020-03-31',DATE '2020-06-30',DATE '2020-09-30',DATE '2020-12-31',DATE '2021-03-31',DATE '2021-06-30',DATE '2021-09-30',DATE '2021-12-31',DATE '2022-03-31',DATE '2022-06-30',DATE '2022-09-30',DATE '2022-12-31',DATE '2023-03-31',DATE '2023-06-30',DATE '2023-09-30',DATE '2023-12-31',DATE '2024-03-31',DATE '2024-06-30',DATE '2024-09-30',DATE '2024-12-31',DATE '2025-03-31',DATE '2025-06-30',DATE '2025-09-30',DATE '2025-12-31',DATE '2026-03-31',DATE '2026-06-30',DATE '2026-09-30')),
q AS (SELECT end_date,count(*) records,count(DISTINCT ts_code) codes,count(*) FILTER(WHERE comp_type='1') general_comp_codes,count(n_cashflow_act) AS n_cashflow_act_nonnull, count(c_fr_sale_sg) AS c_fr_sale_sg_nonnull, count(c_pay_acq_const_fiolta) AS c_pay_acq_const_fiolta_nonnull, count(depr_fa_coga_dpba) AS depr_fa_coga_dpba_nonnull, count(amort_intang_assets) AS amort_intang_assets_nonnull,count(*) FILTER(WHERE ann_date IS NULL OR f_ann_date IS NULL) missing_announcement FROM t GROUP BY end_date)
SELECT jsonb_build_object('section','cashflow_period_coverage','as_of',current_timestamp,'data',coalesce(jsonb_agg(to_jsonb(q) ORDER BY end_date),'[]'::jsonb)) FROM q;
COMMIT;

BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off;
WITH t AS MATERIALIZED (SELECT DISTINCT ON(ts_code,end_date) ts_code,end_date,profit_dedt,q_dtprofit,roe,roic,ann_date FROM raw_tushare.fina_indicator WHERE end_date IN (DATE '2018-12-31',DATE '2019-03-31',DATE '2019-06-30',DATE '2019-09-30',DATE '2019-12-31',DATE '2020-03-31',DATE '2020-06-30',DATE '2020-09-30',DATE '2020-12-31',DATE '2021-03-31',DATE '2021-06-30',DATE '2021-09-30',DATE '2021-12-31',DATE '2022-03-31',DATE '2022-06-30',DATE '2022-09-30',DATE '2022-12-31',DATE '2023-03-31',DATE '2023-06-30',DATE '2023-09-30',DATE '2023-12-31',DATE '2024-03-31',DATE '2024-06-30',DATE '2024-09-30',DATE '2024-12-31',DATE '2025-03-31',DATE '2025-06-30',DATE '2025-09-30',DATE '2025-12-31',DATE '2026-03-31',DATE '2026-06-30',DATE '2026-09-30') ORDER BY ts_code,end_date,CASE update_flag WHEN '1' THEN 0 ELSE 1 END,ann_date DESC,fetched_at DESC,source_content_hash DESC),
q AS (SELECT end_date,count(*) codes,count(profit_dedt) profit_dedt_nonnull,count(q_dtprofit) q_dtprofit_nonnull,count(roe) roe_nonnull,count(roic) roic_nonnull FROM t GROUP BY end_date)
SELECT jsonb_build_object('section','fina_indicator_period_coverage','as_of',current_timestamp,'data',coalesce(jsonb_agg(to_jsonb(q) ORDER BY end_date),'[]'::jsonb)) FROM q;
COMMIT;

BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s';
WITH q AS(SELECT trade_date,idx_type,level,count(*) codes FROM core_serving.dc_index WHERE trade_date=DATE '2026-09-30' GROUP BY trade_date,idx_type,level)
SELECT jsonb_build_object('section','industry_classification','as_of',current_timestamp,'data',jsonb_agg(to_jsonb(q))) FROM q;
COMMIT;
